uv run python -c "
import json
from collections import defaultdict
d=json.load(open('data/analysis/gw4/fixtures.json')); out=d['fixtures']
las=sorted(x['lambda_att'] for x in out); pcs=sorted(x['p_cs'] for x in out)
ta=las[int(len(las)*2/3)]; tp=pcs[int(len(pcs)*2/3)]
print('top-third thresholds: la >= %.2f  pcs >= %.2f'%(ta,tp))
by=defaultdict(list)
for x in out: by[x['club']].append(x)
for c in by: by[c].sort(key=lambda z:z['gw'])
print()
print('--- longest consecutive top-third DEFENCE runs ---')
for c in by:
    best=cur=0; bs=None; s=None
    for i,x in enumerate(by[c]):
        if x['p_cs']>=tp:
            if cur==0: s=i
            cur+=1
            if cur>best: best,bs=cur,s
        else: cur=0
    if best>=3: print('%-4s run %d from GW%d: %s'%(c,best,4+bs,' '.join('%s(%s)%.2f'%(z['opp'],z['venue'],z['p_cs']) for z in by[c][bs:bs+best])))
print()
print('--- longest consecutive top-third ATTACK runs ---')
for c in by:
    best=cur=0; bs=None; s=None
    for i,x in enumerate(by[c]):
        if x['lambda_att']>=ta:
            if cur==0: s=i
            cur+=1
            if cur>best: best,bs=cur,s
        else: cur=0
    if best>=3: print('%-4s run %d from GW%d: %s'%(c,best,4+bs,' '.join('%s(%s)%.2f'%(z['opp'],z['venue'],z['lambda_att']) for z in by[c][bs:bs+best])))
"
